import sys


def main():
    flags = []
    filename = None

    args = sys.argv[1:]
    i = 0
    while i < len(args):
        arg = args[i]
        if arg.startswith('-') and not arg.startswith('--'):
            for ch in arg[1:]:
                if ch in ('l', 'w', 'c'):
                    flags.append(ch)
                else:
                    print(f"Unknown flag: -{ch}", file=sys.stderr)
                    sys.exit(1)
        elif filename is None:
            filename = arg
        else:
            print("Too many arguments", file=sys.stderr)
            sys.exit(1)
        i += 1

    if filename is None or filename == '-':
        data = sys.stdin.buffer.read()
    else:
        with open(filename, 'rb') as f:
            data = f.read()

    num_chars = len(data)
    num_lines = data.count(b'\n')
    # A final line with no trailing newline still counts as a line
    if data and not data.endswith(b'\n'):
        num_lines += 1
    num_words = len(data.split())

    if not flags:
        flags = ['l', 'w', 'c']

    results = []
    for f in flags:
        if f == 'l':
            results.append(str(num_lines))
        elif f == 'w':
            results.append(str(num_words))
        elif f == 'c':
            results.append(str(num_chars))

    print(' '.join(results))


if __name__ == '__main__':
    main()
